from algorithms import shortest_step

def decide(state):
    target = state["exit"]
    for battery in state["items"]:
        if battery["id"] == "battery-a":
            target = [battery["x"], battery["y"]]
            if state["player"] == target:
                return "pick"
            break
    direction = shortest_step(state["tiles"], state["player"], target)
    if direction is None:
        return "wait"
    return direction

while True:
    action = decide(scan())
    if action == "pick":
        pick()
    elif action == "wait":
        wait()
    else:
        move(action)
